using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Xunit;
namespace RPCore.Tests
{
    public class MenuRefinementTests
    {
        static List<MapPin> Pins()=>new List<MapPin>{new MapPin{Name="Casa",X=1,Y=2,Z=3,Extra=new Dictionary<string,JToken>{{"Future","keep"}}}};
        [Fact]public void AddRenameDeletePreserveLegacyShapeAndUnknownFields(){var pins=Pins();Assert.True(MapPinRules.Add(ref pins,"  Trabalho  ",4,5,6,n=>{}));Assert.Equal("Trabalho",pins[1].Name);var old=pins[0];Assert.True(MapPinRules.Rename(ref pins,0,old,"Minha casa",n=>{}));Assert.Equal(3,pins[0].Z);Assert.Equal("keep",(string)pins[0].Extra["Future"]);Assert.True(MapPinRules.Delete(ref pins,1,pins[1],n=>{}));Assert.Single(pins);Assert.Equal("Minha casa",pins[0].Name);}
        [Theory][InlineData("add")][InlineData("rename")][InlineData("delete")]
        public void SaveFailureNeverChangesPinsOrTheirMetadata(string action){var pins=Pins();string before=JsonConvert.SerializeObject(pins);Action<List<MapPin>> fail=n=>throw new IOException();Assert.Throws<IOException>(()=>{if(action=="add")MapPinRules.Add(ref pins,"Novo",4,5,6,fail);else if(action=="rename")MapPinRules.Rename(ref pins,0,pins[0],"Renomeado",fail);else MapPinRules.Delete(ref pins,0,pins[0],fail);});Assert.Equal(before,JsonConvert.SerializeObject(pins));}
        [Fact]public void StaleDeleteConfirmationCannotRemoveAnotherPin(){var pins=Pins();MapPin previous=pins[0];Assert.True(MapPinRules.Rename(ref pins,0,previous,"Outro nome",n=>{}));Assert.False(MapPinRules.Delete(ref pins,0,previous,n=>throw new Exception()));Assert.Single(pins);Assert.Equal("Outro nome",pins[0].Name);}
        [Fact]public void DuplicateNamesAreNotDestructivelyMigrated(){var pins=Pins();Assert.True(MapPinRules.Add(ref pins,"Casa",100,200,300,n=>{}));Assert.True(MapPinRules.Delete(ref pins,1,pins[1],n=>{}));Assert.Equal(1,pins[0].X);}
        [Theory][InlineData("")][InlineData(" ")][InlineData(null)]public void BlankNamesCannotEdit(string name){var pins=Pins();Assert.False(MapPinRules.Add(ref pins,name,1,2,3,n=>throw new Exception()));Assert.False(MapPinRules.Rename(ref pins,0,pins[0],name,n=>throw new Exception()));}
        [Fact]public void LongNameAndFullCapacityLeaveOlderPinsIntact(){var pins=Pins();Assert.False(MapPinRules.Add(ref pins,new string('a',33),1,2,3,n=>throw new Exception()));while(pins.Count<100)Assert.True(MapPinRules.Add(ref pins,"Ponto",1,2,3,n=>{}));Assert.False(MapPinRules.Add(ref pins,"Nao cabe",1,2,3,n=>throw new Exception()));Assert.Equal(100,pins.Count);Assert.Equal("Casa",pins[0].Name);}
        [Theory][InlineData(float.NaN)][InlineData(float.PositiveInfinity)][InlineData(float.NegativeInfinity)]public void InvalidCoordinatesCannotBeSaved(float x){var pins=Pins();Assert.False(MapPinRules.Add(ref pins,"Ponto",x,2,3,n=>throw new Exception()));Assert.Single(pins);}
        [Fact]public void CorruptEntriesAreNotSilentlyFilteredAndOverwritten(){var pins=Pins();pins.Add(null);string before=JsonConvert.SerializeObject(pins);Assert.False(MapPinRules.Add(ref pins,"Novo",1,2,3,n=>throw new Exception()));Assert.False(MapPinRules.Delete(ref pins,0,pins[0],n=>throw new Exception()));Assert.Equal(before,JsonConvert.SerializeObject(pins));}
        [Fact]public void NearestDestinationUsesActualEnabledCandidatesAndHeight(){var far=new GpsDestination{Name="Far",Kind="Fuel",X=10};var above=new GpsDestination{Name="Above",Kind="Fuel",Z=100};var wrong=new GpsDestination{Name="Other",Kind="Grocery",X=0};var invalid=new GpsDestination{Name="Bad",Kind="Fuel",X=float.NaN};Assert.Same(far,MapPinRules.Nearest(new[]{far,above,wrong,invalid},"Fuel",0,0,0));Assert.Null(MapPinRules.Nearest(new[]{wrong},"Fuel",0,0,0));Assert.Null(MapPinRules.Nearest(new[]{far},"Fuel",float.NaN,0,0));}
        [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(7)]
        public void PointerHitsTheSourceSectorCenters(int sector)=>Assert.Equal(sector,RadialMenuRules.Hit(RadialMenuRules.Centers[sector]));
        [Fact]public void RadialCenterOutsideAndInvalidPointerDoNotSelect(){Assert.Equal(-1,RadialMenuRules.Hit(new PointF(960,540)));Assert.Equal(-1,RadialMenuRules.Hit(new PointF(0,0)));Assert.Equal(-1,RadialMenuRules.Hit(new PointF(960,800)));Assert.Equal(-1,RadialMenuRules.Hit(new PointF(float.NaN,540)));}
        [Fact]public void RadialTransformMatchesDrawingInUltrawideAndSafeZone(){float width=3840,s=RadialMenuRules.Scale(width,192,54,1.2f),ox=(width-1920*s)/2,oy=(1080-1080*s)/2;var target=RadialMenuRules.Centers[3];Assert.True(InventoryMouseLayout.Point((ox+target.X*s)/width,(oy+target.Y*s)/1080,width,ox,oy,s,out var p));Assert.Equal(3,RadialMenuRules.Hit(p));Assert.InRange(s,.1f,1.2f);}
        [Fact]public void RadialItemFilterUsesOwnedItemsLayoutAndActualSupportedUses(){var defs=new Dictionary<string,ItemDef>{{"water",new ItemDef{Id="water",Thirst=30}},{"burger",new ItemDef{Id="burger",Hunger=30}},{"bandage",new ItemDef{Id="bandage",Health=40}},{"gun",new ItemDef{Id="gun",Weapon=1}},{"phone",new ItemDef{Id="phone",Action="phone"}},{"material",new ItemDef{Id="material"}}};var counts=defs.Keys.ToDictionary(id=>id,_=>2);var layout=new[]{"material","water","water","gun","bandage","burger","phone","unknown"};Assert.Equal(new[]{"water"},RadialMenuRules.Items(RadialPage.Drinks,defs,counts,layout));Assert.Equal(new[]{"burger"},RadialMenuRules.Items(RadialPage.Food,defs,counts,layout));Assert.Equal(new[]{"bandage"},RadialMenuRules.Items(RadialPage.Health,defs,counts,layout));Assert.Equal(new[]{"gun"},RadialMenuRules.Items(RadialPage.Weapons,defs,counts,layout));Assert.Equal(new[]{"phone"},RadialMenuRules.Items(RadialPage.Tools,defs,counts,layout));counts["water"]=0;Assert.Empty(RadialMenuRules.Items(RadialPage.Drinks,defs,counts,layout));Assert.Equal(2,counts["burger"]);}
        [Fact]public void MedicalDrinkCannotAppearInBothHealthAndDrinks(){var def=new ItemDef{Id="medical",Health=10,Thirst=20};var defs=new Dictionary<string,ItemDef>{{def.Id,def}};var count=new Dictionary<string,int>{{def.Id,1}};Assert.Empty(RadialMenuRules.Items(RadialPage.Drinks,defs,count,null));Assert.Single(RadialMenuRules.Items(RadialPage.Health,defs,count,null));}
        [Theory][InlineData(0,1)][InlineData(6,1)][InlineData(7,2)][InlineData(12,2)][InlineData(13,3)][InlineData(150,25)]public void ItemPaginationKeepsSixActionsAndTwoNavigationSlots(int items,int expected)=>Assert.Equal(expected,RadialMenuRules.Pages(items));
        [Fact]public void AllReferenceEmotesHaveActualDictionaryAndClip(){Assert.Equal(4,ReferenceEmotes.All.Length);Assert.All(ReferenceEmotes.All,e=>{Assert.False(string.IsNullOrWhiteSpace(e.Dictionary));Assert.False(string.IsNullOrWhiteSpace(e.Clip));});Assert.Contains(ReferenceEmotes.All,e=>e.Clip=="handsup_base");}
        [Fact]public void RateChoicesPreserveCustomValuesAndRejectNonfiniteDefaults(){Assert.Contains(1.7f,MenuFileRules.Choices(1.7f,.5f));Assert.Equal(new[]{0f,.5f,1f,1.5f,2f,2.5f},MenuFileRules.Choices(float.NaN,.5f));}
        [Theory][InlineData("false")][InlineData("throw")]
        public void FailedSettingWritePreservesOriginalBytesAndDeletesStage(string failure){string dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string path=Path.Combine(dir,"Interface.ini");File.WriteAllText(path,"[Original]\nFuture=keep\n");string original=File.ReadAllText(path);Assert.Throws<IOException>(()=>MenuFileRules.Write(path,temp=>{File.WriteAllText(temp,"partial");if(failure=="throw")throw new IOException();return false;}));Assert.Equal(original,File.ReadAllText(path));Assert.Single(Directory.GetFiles(dir));}finally{Directory.Delete(dir,true);}}
        [Fact]public void SuccessfulSettingWriteReplacesOnlyTargetAndKeepsPreviousBackup(){string dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string path=Path.Combine(dir,"Interface.ini");File.WriteAllText(path,"old");MenuFileRules.Write(path,temp=>{Assert.Equal("old",File.ReadAllText(temp));File.WriteAllText(temp,"new");return true;});Assert.Equal("new",File.ReadAllText(path));Assert.Equal("old",File.ReadAllText(path+".bak"));MenuFileRules.Write(path,temp=>{File.WriteAllText(temp,"newer");return true;});Assert.Equal("new",File.ReadAllText(path+".bak"));Assert.Equal(2,Directory.GetFiles(dir).Length);}finally{Directory.Delete(dir,true);}}
        [Fact]public void NewSettingFileIsCreatedOnlyAfterSuccessfulWrite(){string dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string path=Path.Combine(dir,"Interface.ini");Assert.Throws<IOException>(()=>MenuFileRules.Write(path,temp=>false));Assert.False(File.Exists(path));MenuFileRules.Write(path,temp=>{File.WriteAllText(temp,"created");return true;});Assert.Equal("created",File.ReadAllText(path));}finally{Directory.Delete(dir,true);}}
    }
}
